INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2024, 'Língua Portuguesa', NULL, 'Q2 Item 1 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 -- PROVA OBJETIVA – PRIMEIRA FASE – MANHÃ -- LÍNGUA PORTUGUESA Texto III Afinal, os homens nascem iguais, apenas sem uma definição completa da natureza. Em Rousseau, por exemplo, com a noção do “bom selvagem”, essa ideia estará absolutamente presente. A alteridade desses “novos homens” transformada em modelo lógico se contrapunha à experiência ocidental. Como concluía Rousseau sobre a origem da desigualdade entre os homens, “se há uma bondade original da natureza h | No quarto parágrafo, o segmento “conformar esse quadro antitético” pode ser entendido como contextualizar, de forma contrária à visão do Iluminismo, a natureza humana.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Língua Portuguesa', NULL, 'Q2 Item 2 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 -- PROVA OBJETIVA – PRIMEIRA FASE – MANHÃ -- LÍNGUA PORTUGUESA Texto III Afinal, os homens nascem iguais, apenas sem uma definição completa da natureza. Em Rousseau, por exemplo, com a noção do “bom selvagem”, essa ideia estará absolutamente presente. A alteridade desses “novos homens” transformada em modelo lógico se contrapunha à experiência ocidental. Como concluía Rousseau sobre a origem da desigualdade entre os homens, “se há uma bondade original da natureza h | No segundo período do quinto parágrafo, o advérbio “simetricamente” transmite a ideia de que, quanto maior o conhecimento sobre os povos colonizados, mais se confirma a tese do bom selvagem.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Língua Portuguesa', NULL, 'Q2 Item 3 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 -- PROVA OBJETIVA – PRIMEIRA FASE – MANHÃ -- LÍNGUA PORTUGUESA Texto III Afinal, os homens nascem iguais, apenas sem uma definição completa da natureza. Em Rousseau, por exemplo, com a noção do “bom selvagem”, essa ideia estará absolutamente presente. A alteridade desses “novos homens” transformada em modelo lógico se contrapunha à experiência ocidental. Como concluía Rousseau sobre a origem da desigualdade entre os homens, “se há uma bondade original da natureza h | Entende-se da leitura do segundo e do terceiro parágrafos que o sentido dado pela autora ao termo “alteridade” é o de distinção entre a humanidade resultante da “experiência ocidental” e da ‘evolução social’ e os outros, caracterizados como o ‘bom selvagem’ e os ‘novos homens’.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Língua Portuguesa', NULL, 'Q2 Item 4 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 -- PROVA OBJETIVA – PRIMEIRA FASE – MANHÃ -- LÍNGUA PORTUGUESA Texto III Afinal, os homens nascem iguais, apenas sem uma definição completa da natureza. Em Rousseau, por exemplo, com a noção do “bom selvagem”, essa ideia estará absolutamente presente. A alteridade desses “novos homens” transformada em modelo lógico se contrapunha à experiência ocidental. Como concluía Rousseau sobre a origem da desigualdade entre os homens, “se há uma bondade original da natureza h | Depreende-se da leitura do texto que Rousseau, ao propor a imagem do ‘bom selvagem’, se alinha à tese, proposta pela Ilustração, de progresso da natureza humana.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Língua Portuguesa', NULL, 'Q3 Item 1 (TPS 2024): Ainda em relação ao texto III, julgue (C ou E) os itens a seguir. | Segundo a autora, a hipótese teórica poligenista tornou-se hegemônica no século XIX.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Língua Portuguesa', NULL, 'Q3 Item 2 (TPS 2024): Ainda em relação ao texto III, julgue (C ou E) os itens a seguir. | Os prefixos presentes nas palavras que designam as correntes “monogenista” e “poligenista” remetem às distintas hipóteses sobre a gênese da humanidade, que contrapõem a unidade da espécie à diversidade racial.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Língua Portuguesa', NULL, 'Q3 Item 3 (TPS 2024): Ainda em relação ao texto III, julgue (C ou E) os itens a seguir. | No primeiro período do quinto parágrafo, a conjunção subordinativa “se” introduz uma condição real, o que é evidenciado pelo modo verbal empregado na oração em que ocorre.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Língua Portuguesa', NULL, 'Q3 Item 4 (TPS 2024): Ainda em relação ao texto III, julgue (C ou E) os itens a seguir. | O segmento “visão idílica” (primeiro período do quinto parágrafo) remete à noção bucólica do ‘bom selvagem’ de Rousseau, que representa um devaneio, uma utopia. Texto IV Assim como aquela senhora hopi que conversava com a pedra, sua irmã, tem um monte de gente que fala com montanhas. No Equador, na Colômbia, em algumas dessas regiões dos Andes, você encontra lugares onde as montanhas formam casais. Tem mãe, pai, filho, tem uma família de montanhas que troca afeto, faz trocas. E as pessoas que vivem nesses vales fazem festas para essas montanhas, dão comida, dão presentes, ganham presentes das montanhas. (...) O tipo de humanidade zumbi que estamos sendo convocados a integrar não tolera tanto prazer, tanta fruição de vida. (...) O Rio Doce, que nós, os Krenak, chamamos de Watu, nosso avô, é', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Língua Portuguesa', NULL, 'Q5 Item 2 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Considerando as ideias e os aspectos linguísticos do texto V, julgue (C ou E) os itens subsequentes. | No texto, percebe-se a intenção do narrador em apresentar uma experiência traumática com a alimentação na infância, algo que seria determinado pela sorte, o destino do ser humano.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Língua Portuguesa', NULL, 'Q5 Item 3 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Considerando as ideias e os aspectos linguísticos do texto V, julgue (C ou E) os itens subsequentes. | Da leitura do segundo parágrafo conclui-se, consideradas a estrutura narrativa da crônica e a sequência temporal empregada no primeiro período desse parágrafo, que a oração “eu era carnívoro”, apesar da flexão verbal no pretérito imperfeito do indicativo, pode ser interpretada como correspondente ao presente do indicativo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Língua Portuguesa', NULL, 'Q5 Item 4 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Considerando as ideias e os aspectos linguísticos do texto V, julgue (C ou E) os itens subsequentes. | Evidencia-se na narrativa que o movimento paredista desencadeia um afastamento do narrador em relação à infância, o que o leva a uma crítica a hábitos adquiridos em seu percurso no sistema educacional e, ao mesmo tempo, a uma defesa da racionalidade humana. CEBRASPE – IRBr – Edital: 2024 Texto V Quando os jornais anunciaram para o dia 1.º deste mês uma parede de açougueiros, a sensação que tive foi muito diversa da de todos os meus concidadãos. Vós ficastes aterrados; eu agradeci o acontecimento ao céu. Boa ocasião para converter esta cidade ao vegetarismo. Não sei se sabem que eu era carnívoro por educação e vegetariano por princípio. Criaram-me a carne, mais carne, ainda carne, sempre carne. Quando cheguei ao uso da razão e organizei o meu código de princípios, incluí nele o vegetarismo;', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Língua Portuguesa', NULL, 'Q6 Item 1 (TPS 2024): No que diz respeito aos aspectos morfossintáticos e semânticos do texto V, julgue (C ou E) os seguintes itens. | Em “Criaram-me a carne” (segundo período do segundo parágrafo), observa-se uma estratégia de indeterminação do sujeito que se explicitaria igualmente com a estrutura Criou-se a carne.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Língua Portuguesa', NULL, 'Q6 Item 2 (TPS 2024): No que diz respeito aos aspectos morfossintáticos e semânticos do texto V, julgue (C ou E) os seguintes itens. | No segundo período do primeiro parágrafo, os elementos da coordenação assindética estão ligados, semanticamente, com base em uma noção de contraste.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Língua Portuguesa', NULL, 'Q6 Item 3 (TPS 2024): No que diz respeito aos aspectos morfossintáticos e semânticos do texto V, julgue (C ou E) os seguintes itens. | Sem prejuízo sintático e semântico do processo narrativo do texto, o primeiro período do primeiro parágrafo poderia ser reestruturado da seguinte maneira: A sensação que tive foi muito diversa da de todos os meus concidadãos quando os jornais anunciaram para o dia 1.º deste mês uma parede de açougueiros.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Língua Portuguesa', NULL, 'Q6 Item 4 (TPS 2024): No que diz respeito aos aspectos morfossintáticos e semânticos do texto V, julgue (C ou E) os seguintes itens. | No primeiro período do texto, o emprego da forma participial tida em lugar da oração “que tive” preservaria as relações sintáticas do período e as relações semânticas estabelecidas entre seus termos. Ainda com base no texto V, julgue (C ou E) os itens que se seguem, relativos a seus aspectos morfossintáticos e semânticos. 1 Em “Os vegetarianos não se batem” (último parágrafo), o pronome “se” que acompanha a forma verbal tem sentido reflexivo, estando subentendida a expressão a si mesmos ao final da oração.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Língua Inglesa', NULL, 'Q8 Item 1 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Texto VI O bife e o vinho compartilham a mitologia sanguínea. É o coração da carne, e qualquer um que a consuma assimila a força do touro. Obviamente, o prestígio do bife deve-se ao seu estado de semicrueza: nele o sangue é simultaneamente visível, denso, compacto e suscetível de ser cortado: imagina-se logo a ambrosia antiga sob a forma de uma matéria pesada que diminui entre os dentes, de modo a fazer com que se sinta ao mesmo tempo a sua força de origem e a sua  | No terceiro período do primeiro parágrafo, a expressão “de modo a” enfatiza o esforço empreendido pelo sujeito da ação expressa pelo verbo “fazer”, podendo ser substituída, sem prejuízo da correção gramatical e da coesão textual, pela expressão com o intuito de.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Língua Inglesa', NULL, 'Q8 Item 2 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Texto VI O bife e o vinho compartilham a mitologia sanguínea. É o coração da carne, e qualquer um que a consuma assimila a força do touro. Obviamente, o prestígio do bife deve-se ao seu estado de semicrueza: nele o sangue é simultaneamente visível, denso, compacto e suscetível de ser cortado: imagina-se logo a ambrosia antiga sob a forma de uma matéria pesada que diminui entre os dentes, de modo a fazer com que se sinta ao mesmo tempo a sua força de origem e a sua  | No trecho “participa de todos os ritmos, desde a confortável refeição burguesa ao lanche boêmio do celibatário” (primeiro período do último parágrafo), a expressão “desde a ... ao ...”, que se refere a uma extensão espacial, não estabelece restrição de ordem no que se refere à estruturação dos elementos espaciais, o que permite a inversão da ordem desses elementos — desde o lanche boêmio do celibatário a confortável refeição burguesa —, sem prejuízo da correção gramatica', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Língua Inglesa', NULL, 'Q8 Item 3 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Texto VI O bife e o vinho compartilham a mitologia sanguínea. É o coração da carne, e qualquer um que a consuma assimila a força do touro. Obviamente, o prestígio do bife deve-se ao seu estado de semicrueza: nele o sangue é simultaneamente visível, denso, compacto e suscetível de ser cortado: imagina-se logo a ambrosia antiga sob a forma de uma matéria pesada que diminui entre os dentes, de modo a fazer com que se sinta ao mesmo tempo a sua força de origem e a sua  | No trecho “e qualquer um que a consuma” (segundo período do primeiro parágrafo), o pronome átono “a”, empregado anaforicamente, poderia ser, correta e coerentemente, substituído por o, em referência a “bife” (primeiro período do primeiro parágrafo), dada a similaridade semântica entre os elementos referenciados.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Língua Inglesa', NULL, 'Q8 Item 4 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Texto VI O bife e o vinho compartilham a mitologia sanguínea. É o coração da carne, e qualquer um que a consuma assimila a força do touro. Obviamente, o prestígio do bife deve-se ao seu estado de semicrueza: nele o sangue é simultaneamente visível, denso, compacto e suscetível de ser cortado: imagina-se logo a ambrosia antiga sob a forma de uma matéria pesada que diminui entre os dentes, de modo a fazer com que se sinta ao mesmo tempo a sua força de origem e a sua  | A grafia das palavras formadas pelo prefixo semi-, como “semicrueza” e semi-inteiro, por exemplo, obedece à mesma regra ortográfica que define a grafia das palavras formadas pelos prefixos co- e re-, no que se refere ao emprego ou não de hífen.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Língua Inglesa', NULL, 'Q9 Item 1 (TPS 2024): Ainda em relação ao texto VI, julgue (C ou E) os itens a seguir. | Na análise crítica de aspectos culturais, o “bife” é caracterizado no texto duplamente como elemento de alienação e como elemento redentor.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Língua Inglesa', NULL, 'Q9 Item 2 (TPS 2024): Ainda em relação ao texto VI, julgue (C ou E) os itens a seguir. | No texto, o autor contesta a ideia do intelecto privilegiado dos intelectuais, o que os coloca na esfera dos mitos da sociedade.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Língua Inglesa', NULL, 'Q9 Item 3 (TPS 2024): Ainda em relação ao texto VI, julgue (C ou E) os itens a seguir. | No texto, a análise de elementos gastronômicos, como o bife, as batatas fritas, com a inclusão do vinho francês, é referenciada com o aporte semântico dos nomes e de sua simbologia, a partir do qual o autor tece sua visão crítica acerca da sociedade capitalista.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Língua Inglesa', NULL, 'Q9 Item 4 (TPS 2024): Ainda em relação ao texto VI, julgue (C ou E) os itens a seguir. | A proposição básica do autor é apontar a alienação do povo, por meio da denúncia da propagação de mensagens fantasiosas na mídia. POLÍTICA INTERNACIONAL Em 30 de maio de 2023, a convite do presidente do Brasil, os líderes dos países sul-americanos reuniram-se em Brasília. O principal tema discutido durante o encontro foi a retomada da agenda de integração regional. O projeto Rotas de Integração e Desenvolvimento Sul-Americano, desenhado pelo Ministério do Planejamento e Orçamento, visa responder à demanda apresentada pelos mandatários durante o encontro. Considerando o projeto mencionado e a integração do Brasil com os países sul-americanos, julgue (C ou E) os itens a seguir. 1 A chamada Rota da Ilha das Guianas, que inclui a Guiana, a Guiana Francesa, o Suriname e a Venezuela, além dos es', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Língua Inglesa', NULL, 'Q11 Item 1 (TPS 2024): Marco da integração sul-americana, o Tratado de Cooperação Amazônica (TCA), assinado, em 1978, por oito países — Brasil, Bolívia, Colômbia, Equador, Guiana, Peru, Suriname e Venezuela —, entrou em vigor em 1980. Em 1998, as oito nações signatárias decidiram criar a Organização do Tratado de Cooperação Amazônica (OTCA), de modo a fortalecer institucionalmente o tratado e conferir-lhe personalidade internacional. Nos dias 8 e 9 de agosto de 2023, foi realizada, no Brasil, a Conferência da Cúpula d | Na reunião em questão, que contou com a presença do presidente francês Emmanuel Macron, aprovou-se a entrada da França na OTCA, dada a condição amazônica da Guiana Francesa, com a expectativa de que a entrada de um país da União Europeia na organização tenha impactos positivos para o financiamento de políticas e programas voltados para o desenvolvimento sustentável da região amazônica.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Língua Inglesa', NULL, 'Q11 Item 2 (TPS 2024): Marco da integração sul-americana, o Tratado de Cooperação Amazônica (TCA), assinado, em 1978, por oito países — Brasil, Bolívia, Colômbia, Equador, Guiana, Peru, Suriname e Venezuela —, entrou em vigor em 1980. Em 1998, as oito nações signatárias decidiram criar a Organização do Tratado de Cooperação Amazônica (OTCA), de modo a fortalecer institucionalmente o tratado e conferir-lhe personalidade internacional. Nos dias 8 e 9 de agosto de 2023, foi realizada, no Brasil, a Conferência da Cúpula d | No dia 9 de agosto de 2023, ainda em Belém, os presidentes dos Estados-partes no TCA mantiveram encontro com mandatários e representantes de países em desenvolvimento de outras regiões do mundo com florestas tropicais, como Indonésia, República Democrática do Congo e República do Congo, tendo sido adotado, na ocasião, o documento Unidos por Nossas Florestas — Comunicado Conjunto dos Países Florestais em Desenvolvimento em Belém, em que conclamam os países desenvolvidos ', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Língua Inglesa', NULL, 'Q11 Item 3 (TPS 2024): Marco da integração sul-americana, o Tratado de Cooperação Amazônica (TCA), assinado, em 1978, por oito países — Brasil, Bolívia, Colômbia, Equador, Guiana, Peru, Suriname e Venezuela —, entrou em vigor em 1980. Em 1998, as oito nações signatárias decidiram criar a Organização do Tratado de Cooperação Amazônica (OTCA), de modo a fortalecer institucionalmente o tratado e conferir-lhe personalidade internacional. Nos dias 8 e 9 de agosto de 2023, foi realizada, no Brasil, a Conferência da Cúpula d | Realizada em Belém do Pará, a reunião contou com a participação de todos os países signatários do TCA, além de representantes de países convidados e de organismos internacionais, tendo sido a primeira reunião de presidentes dos Estados-partes no TCA desde 2009.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Língua Inglesa', NULL, 'Q11 Item 4 (TPS 2024): Marco da integração sul-americana, o Tratado de Cooperação Amazônica (TCA), assinado, em 1978, por oito países — Brasil, Bolívia, Colômbia, Equador, Guiana, Peru, Suriname e Venezuela —, entrou em vigor em 1980. Em 1998, as oito nações signatárias decidiram criar a Organização do Tratado de Cooperação Amazônica (OTCA), de modo a fortalecer institucionalmente o tratado e conferir-lhe personalidade internacional. Nos dias 8 e 9 de agosto de 2023, foi realizada, no Brasil, a Conferência da Cúpula d | Na declaração presidencial emitida por ocasião da reunião, os mandatários dos Estados-partes no TCA concordaram em promover mecanismos inovadores de financiamento para ações climáticas, incluindo a troca de dívidas por ações climáticas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Língua Inglesa', NULL, 'Q12 Item 1 (TPS 2024): As relações entre Brasil e Argentina são marcadas pela intensidade dos fluxos bilaterais de comércio e de investimentos e pela integração da infraestrutura física dos países. Além disso, o perfil do comércio bilateral entre Brasil e Argentina é caracterizado pela grande participação da indústria de transformação e pelo elevado valor agregado dos produtos transacionados, o que atesta a importância desse intercâmbio para a indústria de ambos os países. Acerca das relações socioeconômicas e polític | A construção de gasoduto a partir de Vaca Muerta representa uma janela de oportunidades importante para o Brasil: de um lado, a possibilidade de exportação de insumos brasileiros para a obra; de outro, o fortalecimento da segurança energética nacional e regional.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Língua Inglesa', NULL, 'Q12 Item 2 (TPS 2024): As relações entre Brasil e Argentina são marcadas pela intensidade dos fluxos bilaterais de comércio e de investimentos e pela integração da infraestrutura física dos países. Além disso, o perfil do comércio bilateral entre Brasil e Argentina é caracterizado pela grande participação da indústria de transformação e pelo elevado valor agregado dos produtos transacionados, o que atesta a importância desse intercâmbio para a indústria de ambos os países. Acerca das relações socioeconômicas e polític | A Argentina dispõe de depósitos de hidrocarbonetos não convencionais concentrados sobretudo na província de Neuquén, na área da formação geológica denominada Vaca Muerta, e a importação de gás argentino pelo Brasil poderia contribuir para a superação de desafios brasileiros no setor energético.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Língua Inglesa', NULL, 'Q12 Item 3 (TPS 2024): As relações entre Brasil e Argentina são marcadas pela intensidade dos fluxos bilaterais de comércio e de investimentos e pela integração da infraestrutura física dos países. Além disso, o perfil do comércio bilateral entre Brasil e Argentina é caracterizado pela grande participação da indústria de transformação e pelo elevado valor agregado dos produtos transacionados, o que atesta a importância desse intercâmbio para a indústria de ambos os países. Acerca das relações socioeconômicas e polític | Em 2023, a Argentina foi o terceiro principal destino das exportações brasileiras; com exceção de 2023, nos últimos dez anos, mais de 90% do valor exportado pelo Brasil para a Argentina foi composto de produtos da indústria de transformação.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Língua Inglesa', NULL, 'Q12 Item 4 (TPS 2024): As relações entre Brasil e Argentina são marcadas pela intensidade dos fluxos bilaterais de comércio e de investimentos e pela integração da infraestrutura física dos países. Além disso, o perfil do comércio bilateral entre Brasil e Argentina é caracterizado pela grande participação da indústria de transformação e pelo elevado valor agregado dos produtos transacionados, o que atesta a importância desse intercâmbio para a indústria de ambos os países. Acerca das relações socioeconômicas e polític | A soja é o principal produto agrícola exportado pela Argentina, e, no período de 2022 a 2023, devido a condições climáticas favoráveis, a safra argentina de soja mais que dobrou em relação ao volume da safra anterior, o que resultou em um aumento de 32% nas exportações agropecuárias argentinas para o Brasil no período. Acerca da relação bilateral entre EUA e Brasil, julgue (C ou E) os itens que se seguem. 1 A atual proximidade de posições políticas entre os dois países ', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Língua Inglesa', NULL, 'Q14 Item 1 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Acerca das políticas de integração entre os países da América do Sul, julgue (C ou E) os próximos itens. | As dificuldades de integração energética no Cone Sul estão relacionadas à ausência histórica de intercâmbios de energia e infraestrutura de interconexões das redes de eletricidade e de gás natural entre os países da região.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Língua Inglesa', NULL, 'Q14 Item 2 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Acerca das políticas de integração entre os países da América do Sul, julgue (C ou E) os próximos itens. | É competência do Parlamento do MERCOSUL, conforme seu protocolo constitutivo de dezembro de 2005, velar pela preservação dos regimes democráticos nos Estados-partes.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Língua Inglesa', NULL, 'Q14 Item 3 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Acerca das políticas de integração entre os países da América do Sul, julgue (C ou E) os próximos itens. | Entre as iniciativas que contribuíram para a construção de um espaço de integração sul-americano após a redemocratização do Estado brasileiro, incluem-se a realização da I Reunião dos Chefes de Estado e de Governo da América do Sul e a criação da União das Nações Sul-Americanas (UNASUL).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Língua Inglesa', NULL, 'Q14 Item 4 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Acerca das políticas de integração entre os países da América do Sul, julgue (C ou E) os próximos itens. | Do ano que antecedeu a criação do MERCOSUL até a virada do último milênio, ou seja, aproximadamente nos dez primeiros anos de existência do bloco, o comércio intrazonal mais que quadruplicou. Acerca do G-20 e da presidência brasileira no grupo, julgue (C ou E) os itens a seguir. 1 Em 2024, a União Africana e o BRICS participarão das reuniões do G-20 pela primeira vez como membros plenos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Política Internacional', NULL, 'Q17 Item 1 (TPS 2024): Em relação à agenda internacional do clima, meio ambiente e desenvolvimento sustentável, julgue (C ou E) os itens que se seguem. | Em 2023, o Brasil assinou o acordo sobre conservação e uso sustentável da biodiversidade marinha em áreas além da jurisdição nacional (BBNJ), também conhecido como Tratado do Alto-Mar, o qual, sob a estrutura jurídica da Convenção das Nações Unidas sobre o Direito do Mar (1982), cria mecanismo de repartição de benefícios advindos da exploração científica e econômica de recursos genéticos marinhos em alto-mar.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Política Internacional', NULL, 'Q17 Item 2 (TPS 2024): Em relação à agenda internacional do clima, meio ambiente e desenvolvimento sustentável, julgue (C ou E) os itens que se seguem. | A Convenção-Quadro das Nações Unidas sobre Mudança do Clima (UNFCCC), aberta para assinatura por ocasião da Rio-92, inaugurou o regime multilateral para responder ao desafio do aquecimento global.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Política Internacional', NULL, 'Q17 Item 3 (TPS 2024): Em relação à agenda internacional do clima, meio ambiente e desenvolvimento sustentável, julgue (C ou E) os itens que se seguem. | A Organização do Tratado de Cooperação Amazônica (OTCA), única organização internacional com sede em Brasília, integra como membros todos os países do bioma amazônico, e, como resultado da Cúpula anual dos Países Amazônicos, a Declaração de Belém de 2023 lançou as bases para o fortalecimento institucional da OTCA e reconheceu que a Amazônia atingiu o ponto de não retorno.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Política Internacional', NULL, 'Q17 Item 4 (TPS 2024): Em relação à agenda internacional do clima, meio ambiente e desenvolvimento sustentável, julgue (C ou E) os itens que se seguem. | Foi lançada na COP 28 a iniciativa Missão 1.5, que, direcionada a estimular os países a assumirem maior ambição na segunda rodada de apresentação das Contribuições Nacionalmente Determinadas (NDC), levou em consideração o relatório de 2023 do Painel Intergovernamental sobre Mudança do Clima (IPCC), que reforçou o senso de urgência e gravidade em relação ao perigo de aumento na temperatura global. Considerando a prioridade conferida pelo governo brasileiro às iniciativas de proteção e promoção dos direitos humanos e de direitos sociais junto aos organismos internacionais, julgue (C ou E) os próximos itens. 1 O Brasil copreside a Coalizão Global para a Justiça Social, iniciativa lançada, no início de 2024, pela OIT, organismo que foi criado no contexto do final da Primeira Guerra Mundial e q', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Política Internacional', NULL, 'Q19 Item 1 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 A respeito das temáticas ou tendências globais relevantes para a reflexão e o planejamento estratégico das relações internacionais do Brasil, julgue (C ou E) os seguintes itens. | Com o propósito de promover a integridade da informação e combater as fake news e o discurso de ódio, a ONU aprovou, no primeiro semestre de 2024, a proposta de convenção internacional sobre regulação de plataformas digitais, instrumento inspirado nos princípios da lei sobre serviços digitais da União Europeia.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Política Internacional', NULL, 'Q19 Item 2 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 A respeito das temáticas ou tendências globais relevantes para a reflexão e o planejamento estratégico das relações internacionais do Brasil, julgue (C ou E) os seguintes itens. | Em 2023, observou-se, em relação aos gastos militares globais, o maior aumento anual desde 2009, conforme relatório do Instituto Internacional de Pesquisa para a Paz de Estocolmo (SIPRI); segundo o índice global da paz (GPI), em 2024 foi registrado o maior número de conflitos no mundo, desde a Segunda Guerra Mundial, o que demonstra uma deterioração da paz e da segurança internacionais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Política Internacional', NULL, 'Q19 Item 3 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 A respeito das temáticas ou tendências globais relevantes para a reflexão e o planejamento estratégico das relações internacionais do Brasil, julgue (C ou E) os seguintes itens. | No início de 2024, a OMS adotou um tratado sobre prevenção, prontidão e resposta a pandemias, de cujas negociações o Brasil participou ativamente, tendo defendido amplo acesso a produtos médicos em contextos de emergências sanitárias, assim como a busca por maior diversificação geográfica da produção de insumos e materiais de saúde, com reforço da produção local.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Política Internacional', NULL, 'Q19 Item 4 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 A respeito das temáticas ou tendências globais relevantes para a reflexão e o planejamento estratégico das relações internacionais do Brasil, julgue (C ou E) os seguintes itens. | Em 2020, devido à pandemia de covid-19, aos conflitos armados e aos impactos da crise climática, o progresso na redução da pobreza global desacelerou e a fome no mundo aumentou, à exceção de poucas nações, como o Brasil, que se mantiveram fora do Mapa da Fome, documento elaborado pela FAO. GEOGRAFIA Em relação à distribuição espacial da população no Brasil e no mundo e aos grandes movimentos migratórios intranacionais e internacionais, julgue (C ou E) os itens subsequentes. 1 Nos últimos vinte anos, o Brasil tem experimentado uma maior diversidade nos fluxos migratórios que recebe, destacando-se o aumento das migrações provindas de países vizinhos, especialmente após a implementação do Acordo sobre Residência para Nacionais dos Estados-partes do MERCOSUL e', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Política Internacional', NULL, 'Q21 Item 1 (TPS 2024): No que se refere à estruturação e ao funcionamento do agronegócio no Brasil e no mundo, julgue (C ou E) os próximos itens. | O fato de os saldos comerciais negativos relacionados às importações de insumos necessários para a produção agropecuária não serem considerados no cálculo das exportações líquidas do agronegócio tem pouco impacto na avaliação das exportações de commodities agropecuárias.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Política Internacional', NULL, 'Q21 Item 2 (TPS 2024): No que se refere à estruturação e ao funcionamento do agronegócio no Brasil e no mundo, julgue (C ou E) os próximos itens. | A criação da EMBRAPA, marco importante de avanços significativos no setor agrícola brasileiro, foi resultado de uma política pública que visava ao enfrentamento de problemas graves de abastecimento interno de produtos agrícolas, bem como à expansão e à diversificação das exportações.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Política Internacional', NULL, 'Q21 Item 3 (TPS 2024): No que se refere à estruturação e ao funcionamento do agronegócio no Brasil e no mundo, julgue (C ou E) os próximos itens. | A expansão do agronegócio no Brasil foi impulsionada por investimentos governamentais na modernização da agricultura, assim como pela reforma da política de crédito rural nos anos 80 do século XX.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Política Internacional', NULL, 'Q21 Item 4 (TPS 2024): No que se refere à estruturação e ao funcionamento do agronegócio no Brasil e no mundo, julgue (C ou E) os próximos itens. | A consolidação do mercado internacional de produtos agropecuários tem levado os países importadores a flexibilizar as exigências fitossanitárias e de sustentabilidade dos produtos brasileiros, o que favorece o processo produtivo no Brasil. O espaço, por fim, é o conceito-matriz da identidade da própria Geografia. Embora entendido ora como extensão, ora como plano, ora como estrutura, o espaço é o conceito da totalização de todos os clássicos. Ruy Moreira. O pensamento geográfico brasileiro: as matrizes clássicas originárias. São Paulo: Editora Contexto, 2008. Acerca da categoria espaço nas diferentes matrizes e ontologias da geografia clássica, especialmente nos séculos XIX e XX, julgue (C ou E) os itens a seguir. 1 O geógrafo francês Vidal de La Blache enfatiza em sua obra o método region', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Política Internacional', NULL, 'Q23 Item 1 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Internet: \<slpress.gr>. Na primeira metade do século XX, duas importantes teorias, a do heartland, proposta H. Mackinder, e a do rimland, formulada por Nicholas John Spykman, ambas circunscritas na representação cartográfica precedente, influenciaram a geopolítica. No que se refere à teoria do rimland, julgue (C ou E) os itens a seguir. | A rápida ascensão econômica da China no cenário global a transformou em novo Estado-pivô da Eurásia, o que fez com que os Estados Unidos da América buscassem estratégias para conter a expansão da influência chinesa tanto na bacia do Pacífico quanto em outras regiões de influência norte-americana.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Política Internacional', NULL, 'Q23 Item 2 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Internet: \<slpress.gr>. Na primeira metade do século XX, duas importantes teorias, a do heartland, proposta H. Mackinder, e a do rimland, formulada por Nicholas John Spykman, ambas circunscritas na representação cartográfica precedente, influenciaram a geopolítica. No que se refere à teoria do rimland, julgue (C ou E) os itens a seguir. | Com o fim da União Soviética e a crise do socialismo real, os postulados da teoria do rimland ficaram ultrapassados, tendo a OTAN perdido sua influência como bloco militar em face da emergência de blocos geoeconômicos como a União Europeia (UE), a OCDE e o NAFTA.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Política Internacional', NULL, 'Q23 Item 3 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Internet: \<slpress.gr>. Na primeira metade do século XX, duas importantes teorias, a do heartland, proposta H. Mackinder, e a do rimland, formulada por Nicholas John Spykman, ambas circunscritas na representação cartográfica precedente, influenciaram a geopolítica. No que se refere à teoria do rimland, julgue (C ou E) os itens a seguir. | Também conhecida como teoria do choque das civilizações, a teoria do rimland, cuja proposta se concentra na estratégia de conter a expansão de movimentos contrários ao Ocidente no Oriente Médio, norte da África, Cáucaso e Leste europeu, a partir da adoção de políticas de fomento à economia financiadas pelos Estados Unidos da América, dominou o debate geopolítico no período que sucedeu a Segunda Guerra Mundial.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Política Internacional', NULL, 'Q23 Item 4 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Internet: \<slpress.gr>. Na primeira metade do século XX, duas importantes teorias, a do heartland, proposta H. Mackinder, e a do rimland, formulada por Nicholas John Spykman, ambas circunscritas na representação cartográfica precedente, influenciaram a geopolítica. No que se refere à teoria do rimland, julgue (C ou E) os itens a seguir. | Atualmente, Ucrânia e Taiwan constituem centros de tensão geopolítica que envolvem objetivos estratégicos de competição entre as potências contemporâneas Estados Unidos da América, Rússia e China.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Política Internacional', NULL, 'Q24 Item 1 (TPS 2024): No ano de 2024, intensificou-se o debate público sobre a Proposta de Emenda à Constituição (PEC) n.º 3/2022, que visa modificar a Constituição Federal de 1988, estabelecendo novas diretrizes para a propriedade e gestão dos terrenos de marinha. O debate começou com uma audiência pública no Senado Federal para debater a PEC, ocasião em que a Secretaria de Patrimônio da União do Ministério da Gestão e da Inovação em Serviços Públicos se posicionou contra a proposta. Internet: \<gov.br> (com adaptaç | Há diversos usos econômicos e ações de preservação ambiental na costa brasileira e nos terrenos de marinha, como a instalação de portos, usinas eólicas, indústrias, exploração mineral, pesca, infraestruturas militares, unidades de conservação, turismo e empreendimentos imobiliários, o que justifica o caráter estratégico do litoral para a defesa e desenvolvimento econômico do país.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Política Internacional', NULL, 'Q24 Item 2 (TPS 2024): No ano de 2024, intensificou-se o debate público sobre a Proposta de Emenda à Constituição (PEC) n.º 3/2022, que visa modificar a Constituição Federal de 1988, estabelecendo novas diretrizes para a propriedade e gestão dos terrenos de marinha. O debate começou com uma audiência pública no Senado Federal para debater a PEC, ocasião em que a Secretaria de Patrimônio da União do Ministério da Gestão e da Inovação em Serviços Públicos se posicionou contra a proposta. Internet: \<gov.br> (com adaptaç | As áreas definidas como terrenos de marinha são estratégicas para a exploração de recursos naturais como o sal marinho, o petróleo e o gás e, devido a sua fragilidade ambiental e aos riscos de acidentes e desastres naturais a que estão sujeitas, são consideradas áreas restritas, nas quais é proibida a ocupação humana, como moradia, por exemplo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Política Internacional', NULL, 'Q24 Item 3 (TPS 2024): No ano de 2024, intensificou-se o debate público sobre a Proposta de Emenda à Constituição (PEC) n.º 3/2022, que visa modificar a Constituição Federal de 1988, estabelecendo novas diretrizes para a propriedade e gestão dos terrenos de marinha. O debate começou com uma audiência pública no Senado Federal para debater a PEC, ocasião em que a Secretaria de Patrimônio da União do Ministério da Gestão e da Inovação em Serviços Públicos se posicionou contra a proposta. Internet: \<gov.br> (com adaptaç | Os terrenos de marinha são extensões de terra ao longo da costa marítima ou próximas a rios, lagos e lagoas que sofrem a influência das marés oceânicas. No caso da costa marítima, esses terrenos correspondem a 33 metros contados a partir do mar em direção ao continente ou ao interior de ilhas costeiras.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Política Internacional', NULL, 'Q24 Item 4 (TPS 2024): No ano de 2024, intensificou-se o debate público sobre a Proposta de Emenda à Constituição (PEC) n.º 3/2022, que visa modificar a Constituição Federal de 1988, estabelecendo novas diretrizes para a propriedade e gestão dos terrenos de marinha. O debate começou com uma audiência pública no Senado Federal para debater a PEC, ocasião em que a Secretaria de Patrimônio da União do Ministério da Gestão e da Inovação em Serviços Públicos se posicionou contra a proposta. Internet: \<gov.br> (com adaptaç | Segundo a Constituição Federal de 1988, os terrenos de marinha podem ser públicos ou privados, garantindo o texto constitucional que as propriedades privadas definidas como terrenos de marinha sejam passíveis de demarcação, escrituração, venda, aluguel, doação ou herança. No que se refere às fronteiras e às formas de apropriação política do espaço geográfico, julgue (C ou E) os itens subsequentes. 1 Segundo a teoria da mundialização, defendida a partir dos anos noventa ', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Política Internacional', NULL, 'Q26 Item 1 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Considerando que o direito internacional se desenvolve, entre outros meios, pela elaboração de tratados internacionais e de decisões de tribunais internacionais, julgue (C ou E) os itens seguintes, a respeito do desenvolvimento do direito internacional contemporâneo. | As intervenções de terceiros Estados em procedimentos contenciosos na Corte Internacional de Justiça (CIJ) têm aumentado em número, o que levou a Corte a ajustar suas regras de procedimento para intervenções de terceiros Estados.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Política Internacional', NULL, 'Q26 Item 2 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Considerando que o direito internacional se desenvolve, entre outros meios, pela elaboração de tratados internacionais e de decisões de tribunais internacionais, julgue (C ou E) os itens seguintes, a respeito do desenvolvimento do direito internacional contemporâneo. | Segundo o jurista brasileiro Antônio Augusto Cançado Trindade, verifica-se, no direito internacional contemporâneo, um retorno às teorias clássicas do direito internacional público, em processo histórico de humanização do direito internacional.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Política Internacional', NULL, 'Q26 Item 3 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Considerando que o direito internacional se desenvolve, entre outros meios, pela elaboração de tratados internacionais e de decisões de tribunais internacionais, julgue (C ou E) os itens seguintes, a respeito do desenvolvimento do direito internacional contemporâneo. | O acordo para conservação e uso sustentável da diversidade biológica marinha em áreas para além da jurisdição nacional (Acordo BBNJ) tem, como um de seus princípios norteadores, o princípio do patrimônio comum da humanidade, o qual já estava previsto na Convenção das Nações Unidas sobre o Direito do Mar (CNUDM).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Política Internacional', NULL, 'Q26 Item 4 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Considerando que o direito internacional se desenvolve, entre outros meios, pela elaboração de tratados internacionais e de decisões de tribunais internacionais, julgue (C ou E) os itens seguintes, a respeito do desenvolvimento do direito internacional contemporâneo. | O crescente recurso a instâncias judiciais internacionais estendeu-se, nos últimos anos, às questões atinentes à mudança do clima, com pedidos de opinião consultiva dirigidos à Corte Internacional de Justiça (CIJ), ao Tribunal de Direito do Mar e à Comissão Interamericana de Direitos Humanos. Julgue (C ou E) os seguintes itens, acerca dos princípios que regem o Brasil em suas relações internacionais. 1 O princípio da não intervenção, segundo o qual é direito de cada Estado soberano conduzir seus assuntos sem intervenção externa, foi reconhecido pela Assembleia Geral das Nações Unidas como condição essencial para a convivência pacífica entre as nações.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Geografia', NULL, 'Q28 Item 1 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 DIREITO Considerando a definição e os elementos constitutivos do Estado, julgue (C ou E) os itens a seguir. | Os direitos de soberania do Estado costeiro sobre sua plataforma continental não afetam o regime jurídico das águas sobrejacentes.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Geografia', NULL, 'Q28 Item 2 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 DIREITO Considerando a definição e os elementos constitutivos do Estado, julgue (C ou E) os itens a seguir. | No âmbito do direito internacional, é pacífico o entendimento de que os Estados que venham a perder integralmente seu território em razão da elevação do nível do mar sejam considerados extintos, dada a perda de um dos elementos constitutivos essenciais da condição de Estado.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Geografia', NULL, 'Q28 Item 3 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 DIREITO Considerando a definição e os elementos constitutivos do Estado, julgue (C ou E) os itens a seguir. | Conforme decisão do Tribunal Penal Internacional (TPI), sua jurisdição se estende a crimes cometidos no território de Estado-parte no Estatuto de Roma, sendo desnecessário determinar a existência dos elementos essenciais para que este Estado-parte seja considerado Estado conforme o direito internacional geral.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Geografia', NULL, 'Q28 Item 4 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 DIREITO Considerando a definição e os elementos constitutivos do Estado, julgue (C ou E) os itens a seguir. | Segundo posição adotada pelo Brasil no âmbito das discussões multilaterais sobre aplicação do direito internacional a tecnologias de informação e comunicação, a soberania do Estado estende-se ao uso dessas tecnologias. Julgue (C ou E) os itens seguintes, acerca das imunidades diplomáticas, considerando as normas aplicáveis ao tema e a jurisprudência do STF acerca da matéria. 1 Agente diplomático que exerça profissão liberal ou atividade comercial no Estado acreditado fora de suas funções oficiais pode ser processado na esfera civil e administrativa, podendo até sofrer medida de execução, a menos que tal medida venha a macular a inviolabilidade de sua pessoa ou de sua residência.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Geografia', NULL, 'Q30 Item 1 (TPS 2024): Acerca do uso da força no âmbito do direito internacional, julgue (C ou E) os seguintes itens. | Segundo a Carta das Nações Unidas, o exercício do direito à legítima defesa por Estado-membro das Nações Unidas deve ser informado imediatamente ao Conselho de Segurança e restringe as ações desse órgão da ONU na tomada de providências para manter ou restabelecer a paz e a segurança internacionais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Geografia', NULL, 'Q30 Item 2 (TPS 2024): Acerca do uso da força no âmbito do direito internacional, julgue (C ou E) os seguintes itens. | Nos termos da Carta das Nações Unidas, a represália é uma das formas lícitas de o Estado agredido exercer seu direito à legítima defesa.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Geografia', NULL, 'Q30 Item 3 (TPS 2024): Acerca do uso da força no âmbito do direito internacional, julgue (C ou E) os seguintes itens. | Com a evolução da prática e da doutrina internacionais relacionadas ao direito à legítima defesa consagrado na Carta das Nações Unidas, o conceito de legítima defesa preventiva passou a ser aceito por crescente número de países, inclusive pelo Brasil.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Geografia', NULL, 'Q30 Item 4 (TPS 2024): Acerca do uso da força no âmbito do direito internacional, julgue (C ou E) os seguintes itens. | O Brasil, empenhado em criar zona de paz e cooperação em seu entorno geográfico, não integra qualquer acordo regional inspirado no artigo 51 da Carta das Nações Unidas, segundo o qual o exercício do direito inerente de legítima defesa contempla duas modalidades, a legítima defesa individual e a legítima defesa coletiva. Em relação ao Tribunal Penal Internacional (TPI), ao Estatuto de Roma e às resoluções do CSNU, julgue (C ou E) os itens que se seguem. 1 Uma das principais críticas de parte da doutrina ao Estatuto de Roma refere-se ao fato de o procurador do TPI não deter a iniciativa de abrir inquérito com base em informações sobre a prática de crimes da competência do tribunal, dependendo, para tanto, de anuência do Estado-parte ou de denúncia proveniente do Conselho de Segurança da ONU.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Geografia', NULL, 'Q32 Item 1 (TPS 2024): No que se refere ao direito internacional humanitário, julgue (C ou E) os itens subsequentes. | Uma das normas básicas do Direito Internacional Humanitário, o princípio da distinção obriga os beligerantes a distinguir, em todas as circunstâncias, entre pessoas e bens civis, por um lado, e combatentes e objetivos militares, por outro lado, e os civis que temporariamente participem diretamente das hostilidades continuam amparados por essa norma fundamental.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Geografia', NULL, 'Q32 Item 2 (TPS 2024): No que se refere ao direito internacional humanitário, julgue (C ou E) os itens subsequentes. | De acordo com o princípio da proporcionalidade, ainda que determinado alvo de ataque seja militarmente legítimo, não deverá haver ataque se os danos civis colaterais forem desproporcionais ao ganho militar dele advindo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Geografia', NULL, 'Q32 Item 3 (TPS 2024): No que se refere ao direito internacional humanitário, julgue (C ou E) os itens subsequentes. | A Convenção Internacional sobre a Proibição do Desenvolvimento, Produção, Estocagem e Uso de Armas Químicas e sobre a Destruição das Armas Químicas Existentes no Mundo, assinada em Paris, em 1993, baniu o emprego de tais armas, seu desenvolvimento, seu armazenamento e sua transferência, além de exigir a destruição dos arsenais, embora o cumprimento da última obrigação obedeça, via de regra, a discricionariedade de cada Estado-parte da convenção.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Geografia', NULL, 'Q32 Item 4 (TPS 2024): No que se refere ao direito internacional humanitário, julgue (C ou E) os itens subsequentes. | Embora a Corte Internacional de Justiça não tenha determinado, em sua Opinião Consultiva (1996), a licitude ou ilicitude do uso de armas nucleares, os efeitos indiscriminados das armas nucleares suscitam questionamentos quanto à sua compatibilidade com o direito internacional humanitário, especialmente no que tange aos princípios da distinção e da humanidade. Espaço livre', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Geografia', NULL, 'Q33 Item 1 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Based on text I, judge whether the following statements are right (C) or wrong (E). | The text stresses the difference between the opinions of cave artists and of modern art scholars in terms of the concept of the artistic genius.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Geografia', NULL, 'Q33 Item 2 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Based on text I, judge whether the following statements are right (C) or wrong (E). | The author sides with those who take cave art to be a ‘great spiritual symbol’, as stated in the first paragraph.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Geografia', NULL, 'Q33 Item 3 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Based on text I, judge whether the following statements are right (C) or wrong (E). | The text suggests that 20th-century scholars had an erroneous perspective on how cave art should be viewed.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Geografia', NULL, 'Q33 Item 4 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Based on text I, judge whether the following statements are right (C) or wrong (E). | The author concludes that cave artists depicted humans as weak to show the preponderance megafauna had in those days. CEBRASPE – IRBr – Edital: 2024 -- PROVA OBJETIVA – PRIMEIRA FASE – TARDE -- LÍNGUA INGLESA Text I Despite the tricky and life-threatening relationship between Paleolithic humans and the megafauna that comprised so much of their environment, twentieth-century scholars tended to claim cave art as evidence of an unalloyed triumph for our species. It was a “great spiritual symbol,” of a time when “man had just emerged from a purely zoological existence, when instead of being dominated by animals, he began to dominate them.” But the child-like and highly stylized stick figures found in caves do not radiate triumph. By the standards of our own time, they are excessively self-effa', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q34 Item 1 (TPS 2024): Judge whether the following items about text I are right (C) or wrong (E). | In the last sentence of the text, inserting a comma immediately after the first occurrence of “that” would make the sentence grammatically incorrect.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q34 Item 2 (TPS 2024): Judge whether the following items about text I are right (C) or wrong (E). | In the expressions “unalloyed triumph” (first sentence of the text) and “sheer silliness” (first sentence of the second paragraph), the adjectives “unalloyed” and “sheer” convey similar meanings.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q34 Item 3 (TPS 2024): Judge whether the following items about text I are right (C) or wrong (E). | The last sentence of the second paragraph could be rewritten, maintaining its original meaning and correctness, as: Accordingly, Judith Thurman has already written that cave artists, notwithstanding their respect for naturalistic portraits, have an aversion to painting human beings with traces of crudeness, which suggests mockery.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q34 Item 4 (TPS 2024): Judge whether the following items about text I are right (C) or wrong (E). | By stating that the human figures in cave art are “self-effacing” (last sentence of the first paragraph), the author means that humans were virtually absent characters in cave paintings. Text II This book wants to show the newcomer the lie of the land without confusing him with details. In writing it I thought first and foremost of readers in their teens. But I have never believed that books for young people should differ from books for adults except for the fact that they must reckon with the most exacting class of critics, critics who are quick to detect and resent any trace of pretentious jargon or bogus sentiment. I know from experience that these are the vices which may render people suspicious of all writings. I have striven to use plain language even at the risk of sounding casual o', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q35 Item 1 (TPS 2024): Considering text II, judge whether the following statements are right (C) or wrong (E). | As used in the third sentence of the first paragraph, the expression “most exacting class of critics” refers to critics who worry too much about being correct.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q35 Item 2 (TPS 2024): Considering text II, judge whether the following statements are right (C) or wrong (E). | In the fragment “most exacting class of critics, critics who are quick to (…)” (third sentence of the first paragraph), omitting the second occurrence of the word “critics” would maintain the grammar correctness of the sentence.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q35 Item 3 (TPS 2024): Considering text II, judge whether the following statements are right (C) or wrong (E). | By stating that he wants to show the reader “the lie of the land” (first sentence of the text), the author means that he wants to inform the reader of the rules he followed in writing the book.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q35 Item 4 (TPS 2024): Considering text II, judge whether the following statements are right (C) or wrong (E). | In the fragment “I have never believed that books for young people should differ from books for adults except for the fact that they must reckon with the most exacting class of critics” (third sentence of the first paragraph), the referent for the pronoun “they” is “adults”. Based on text II, judge whether the following statements are right (C) or wrong (E). 1 In the last sentence of the text, the word “dog” has a similar meaning to trouble.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q37 Item 1 (TPS 2024): Text III Aside from the difficulties of operating a decidedly multinational staff organization, once it is formed, the problem of reconciling the principle of equitable geographical distribution of recruits with that of “securing the highest standards of efficiency, competence, and integrity” is a formidable one. This delicate task was politically imposed upon the League of Nations secretary-general, and is constitutionally required of his counterpart in the United Nations. For better or for wor | The author of the text considers that, more than the competence of the applicants or their nationality, it is their political connections — who they know — that has the greatest impact on their chance of being recruited for international jobs.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q37 Item 2 (TPS 2024): Text III Aside from the difficulties of operating a decidedly multinational staff organization, once it is formed, the problem of reconciling the principle of equitable geographical distribution of recruits with that of “securing the highest standards of efficiency, competence, and integrity” is a formidable one. This delicate task was politically imposed upon the League of Nations secretary-general, and is constitutionally required of his counterpart in the United Nations. For better or for wor | According to the text, reconciling the principle of equitable geographical distribution of recruits with that of securing the highest standards of efficiency, competence, and integrity was a legal obligation incumbent both on the Secretary-General of the League of Nations and the Secretary-General of the United Nations.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q37 Item 3 (TPS 2024): Text III Aside from the difficulties of operating a decidedly multinational staff organization, once it is formed, the problem of reconciling the principle of equitable geographical distribution of recruits with that of “securing the highest standards of efficiency, competence, and integrity” is a formidable one. This delicate task was politically imposed upon the League of Nations secretary-general, and is constitutionally required of his counterpart in the United Nations. For better or for wor | The fragment “even at the expense of sheer quality” (last sentence of the second paragraph) could be, without harming the coherence of the text, replaced with even if this entails the choice of less qualified applicants.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q37 Item 4 (TPS 2024): Text III Aside from the difficulties of operating a decidedly multinational staff organization, once it is formed, the problem of reconciling the principle of equitable geographical distribution of recruits with that of “securing the highest standards of efficiency, competence, and integrity” is a formidable one. This delicate task was politically imposed upon the League of Nations secretary-general, and is constitutionally required of his counterpart in the United Nations. For better or for wor | The excerpt “It licenses a kind of international spoils system” could be, without altering the meaning of the sentence, replaced with It spoils the international system.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q38 Item 1 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Text IV In the middle of July, Roger was making his first ministerial speech. I did not need reminding, having drafted enough of them, how much speeches mattered — to parliamentary bosses, to any kind of tycoon. Draft after draft: the search for the supreme, the impossible, the more than Flaubertian perfection; the scrutiny for any phrase that said more than it ought to say, so that each speech at the end was bound, by the law of official inexplicitness, to be more | In the third sentence of the text, “supreme” is an adjective modifying the noun “perfection”.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q38 Item 2 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Text IV In the middle of July, Roger was making his first ministerial speech. I did not need reminding, having drafted enough of them, how much speeches mattered — to parliamentary bosses, to any kind of tycoon. Draft after draft: the search for the supreme, the impossible, the more than Flaubertian perfection; the scrutiny for any phrase that said more than it ought to say, so that each speech at the end was bound, by the law of official inexplicitness, to be more | The text suggests that, when their original drafts were modified by a minister, Hector and Douglas would stand up to him and insist on retaining the sharp, clear English of the original.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q38 Item 3 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Text IV In the middle of July, Roger was making his first ministerial speech. I did not need reminding, having drafted enough of them, how much speeches mattered — to parliamentary bosses, to any kind of tycoon. Draft after draft: the search for the supreme, the impossible, the more than Flaubertian perfection; the scrutiny for any phrase that said more than it ought to say, so that each speech at the end was bound, by the law of official inexplicitness, to be more | In the first sentence of the text, the verb “making” is being used with the sense of writing.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q38 Item 4 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Text IV In the middle of July, Roger was making his first ministerial speech. I did not need reminding, having drafted enough of them, how much speeches mattered — to parliamentary bosses, to any kind of tycoon. Draft after draft: the search for the supreme, the impossible, the more than Flaubertian perfection; the scrutiny for any phrase that said more than it ought to say, so that each speech at the end was bound, by the law of official inexplicitness, to be more | The narrator of the text considers that the process of rewriting the speech multiple times contributes to its becoming more focused and direct. Espaço livre', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q39 Item 2 (TPS 2024): Text V Urbanization is one of the defining trends of this century and a key driver of development. By 2050, around 70% of the world’s population will be living in cities and towns. Asia and Africa will collectively account for a significant majority of the urban growth rate, a development that reflects the growth of both ‘megacities’ and smaller urban settlements in both regions over the past three decades. Today, cities produce around 80% of the global GDP and this importance is likely to conti | To ensure equal and inclusive access to services and create urban spaces that improve livability, cities should be developed by citizens aiming to fully realize their potential.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q39 Item 3 (TPS 2024): Text V Urbanization is one of the defining trends of this century and a key driver of development. By 2050, around 70% of the world’s population will be living in cities and towns. Asia and Africa will collectively account for a significant majority of the urban growth rate, a development that reflects the growth of both ‘megacities’ and smaller urban settlements in both regions over the past three decades. Today, cities produce around 80% of the global GDP and this importance is likely to conti | Due to the amount of global GDP produced by cities, the article shows how important it is for cities to continue growing to help the urbanization process.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q39 Item 4 (TPS 2024): Text V Urbanization is one of the defining trends of this century and a key driver of development. By 2050, around 70% of the world’s population will be living in cities and towns. Asia and Africa will collectively account for a significant majority of the urban growth rate, a development that reflects the growth of both ‘megacities’ and smaller urban settlements in both regions over the past three decades. Today, cities produce around 80% of the global GDP and this importance is likely to conti | Despite the many vulnerabilities and threats cities encounter, it is reasonable to conclude that with effective planning, policies, and adequate support, urbanization can avoid unnecessary risks and costs, enabling cities to achieve their full potential.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q40 Item 1 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Em relação à economia e à sociedade da América portuguesa, julgue (C ou E) os itens a seguir. | Tendo reconhecido o Tratado de Tordesilhas, a França negociou com Portugal parcerias comerciais para a exploração conjunta da Guanabara (século XVI) e do Maranhão (século XVII), sem ameaçar a posse das terras brasileiras pelo colonizador luso.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q40 Item 2 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Em relação à economia e à sociedade da América portuguesa, julgue (C ou E) os itens a seguir. | Apesar de a escravidão indígena ter sido proibida pela legislação portuguesa, comunidades indígenas foram escravizadas pelos colonizadores com base nas exceções da lei, a exemplo do ocorrido durante as chamadas guerras justas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q40 Item 3 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Em relação à economia e à sociedade da América portuguesa, julgue (C ou E) os itens a seguir. | No século XVII, a presença holandesa nas capitanias do norte contribuiu para a diversificação da economia da região, o que se comprovou pelo crescimento das atividades de criação de caprinos e bovinos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q40 Item 4 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Em relação à economia e à sociedade da América portuguesa, julgue (C ou E) os itens a seguir. | No curso dos primeiros cinco anos após a chegada dos portugueses ao Brasil, a Coroa portuguesa arrendou o litoral brasileiro a um consórcio de comerciantes lisboetas, com o intuito de iniciar e expandir a exploração do novo território e nele construir uma feitoria. Acerca do período da Primeira República no Brasil, julgue (C ou E) os itens seguintes. 1 O Manifesto Antropófago, de Oswald de Andrade, tematizou a tensão (deglutição crítica do outro) entre culturas ameríndias e africanas e a cultura europeia, diferenciando-se assim das proposições assimilacionistas do indigenismo romântico do século XIX.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q43 Item 1 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 HISTÓRIA DO BRASIL A respeito da Cabanagem, julgue (C ou E) os itens seguintes. | A significativa participação de escravizados na revolta fez prevalecer, como senso comum, a associação dos membros do movimento ao mal, assim como despertou na sociedade da época o medo de que ocorresse no país o que se passara no Haiti.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q43 Item 2 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 HISTÓRIA DO BRASIL A respeito da Cabanagem, julgue (C ou E) os itens seguintes. | O movimento pregava o fim da regência com o estabelecimento de uma república a exemplo das ex-colônias espanholas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q43 Item 3 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 HISTÓRIA DO BRASIL A respeito da Cabanagem, julgue (C ou E) os itens seguintes. | Após longos confrontos com as tropas legalistas, a rebelião foi controlada, ao custo da destruição de Belém e de sua economia, bem como da dizimação de cerca de 1/5 da população estimada da província.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q46 Item 1 (TPS 2024): A República Liberal (1945-1964) foi um período marcado pela inclusão de novos setores da sociedade no cenário político e a intensificação das disputas por diferentes projetos de sociedade e de cidadania. A respeito desse período, julgue (C ou E) os itens a seguir. | A Constituição de 1946 reconheceu a educação básica como direito, estabeleceu a gratuidade do ensino primário, bem como definiu os percentuais da arrecadação fiscal que deveriam ser investidos no setor educacional pela União, estados e municípios.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q46 Item 2 (TPS 2024): A República Liberal (1945-1964) foi um período marcado pela inclusão de novos setores da sociedade no cenário político e a intensificação das disputas por diferentes projetos de sociedade e de cidadania. A respeito desse período, julgue (C ou E) os itens a seguir. | Em 1963, a repressão comandada por João Goulart à insurreição dos suboficiais ampliou o apoio dado ao governo pelos oficiais legalistas que haviam se oposto às tentativas de golpe ocorridas desde o final do segundo governo Vargas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q46 Item 3 (TPS 2024): A República Liberal (1945-1964) foi um período marcado pela inclusão de novos setores da sociedade no cenário político e a intensificação das disputas por diferentes projetos de sociedade e de cidadania. A respeito desse período, julgue (C ou E) os itens a seguir. | Mudaram a experiência política brasileira a partir de 1945: a instituição da obrigação de abrangência nacional na organização dos partidos políticos, maior inserção da sociedade civil no debate político e o estabelecimento do voto secreto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História do Brasil', NULL, 'Q46 Item 4 (TPS 2024): A República Liberal (1945-1964) foi um período marcado pela inclusão de novos setores da sociedade no cenário político e a intensificação das disputas por diferentes projetos de sociedade e de cidadania. A respeito desse período, julgue (C ou E) os itens a seguir. | Nesse período, o incremento da urbanização do Brasil vinculava-se, por um lado, ao acelerado processo de industrialização nas grandes cidades e, por outro, aos esforços estatais de ocupação e povoamento do interior do país. Considerando o período do Regime Militar no Brasil, julgue (C ou E) os itens a seguir. 1 Denunciado à Comissão de Direitos Humanos da ONU no relatório da Anistia Internacional de 1972, o Brasil foi impedido de participar como membro daquela comissão até a abertura política do país, em meados da década de 80 do século XX.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'História Mundial', NULL, 'Q49 Item 1 (TPS 2024): A ênfase, portanto, incide mais sobre o profundo do que sobre o rápido. Não surpreenderá ninguém que os extraordinários avanços tecnológicos da grande Revolução Industrial não fossem realizados da noite para o dia. Poucas invenções surgem maduras no mundo. Pelo contrário: precisa-se de uma série de pequenos grandes aperfeiçoamentos para que uma ideia se converta numa técnica. David S. A. Landes. A riqueza e a pobreza das nações. Rio de Janeiro: Editora Campus, 1998, p. 207 (com adaptações). Cons | Secundário em relação ao liberalismo, o colonialismo não teve impacto imediato na política e na economia do século XIX.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História Mundial', NULL, 'Q49 Item 2 (TPS 2024): A ênfase, portanto, incide mais sobre o profundo do que sobre o rápido. Não surpreenderá ninguém que os extraordinários avanços tecnológicos da grande Revolução Industrial não fossem realizados da noite para o dia. Poucas invenções surgem maduras no mundo. Pelo contrário: precisa-se de uma série de pequenos grandes aperfeiçoamentos para que uma ideia se converta numa técnica. David S. A. Landes. A riqueza e a pobreza das nações. Rio de Janeiro: Editora Campus, 1998, p. 207 (com adaptações). Cons | Segundo historiadores e pensadores, a concepção de nacionalismo e, principalmente, de nação engloba a consideração da existência de uma comunidade imaginada como intrinsecamente limitada e, simultaneamente, soberana.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'História Mundial', NULL, 'Q49 Item 3 (TPS 2024): A ênfase, portanto, incide mais sobre o profundo do que sobre o rápido. Não surpreenderá ninguém que os extraordinários avanços tecnológicos da grande Revolução Industrial não fossem realizados da noite para o dia. Poucas invenções surgem maduras no mundo. Pelo contrário: precisa-se de uma série de pequenos grandes aperfeiçoamentos para que uma ideia se converta numa técnica. David S. A. Landes. A riqueza e a pobreza das nações. Rio de Janeiro: Editora Campus, 1998, p. 207 (com adaptações). Cons | Desigual e demorada em seus efeitos no quadro geral dos povos e nações onde se instalou, a Revolução Industrial promoveu o surgimento de novas profissões em substituição a antigas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'História Mundial', NULL, 'Q49 Item 4 (TPS 2024): A ênfase, portanto, incide mais sobre o profundo do que sobre o rápido. Não surpreenderá ninguém que os extraordinários avanços tecnológicos da grande Revolução Industrial não fossem realizados da noite para o dia. Poucas invenções surgem maduras no mundo. Pelo contrário: precisa-se de uma série de pequenos grandes aperfeiçoamentos para que uma ideia se converta numa técnica. David S. A. Landes. A riqueza e a pobreza das nações. Rio de Janeiro: Editora Campus, 1998, p. 207 (com adaptações). Cons | Com o advento da Revolução Industrial, o uso econômico do tempo foi rapidamente assimilado pelos trabalhadores das fábricas e dos demais setores produtivos, tendo os aspectos culturais e as formas de execução de tarefas do cotidiano se adequado simultaneamente às novas exigências laborais do capitalismo incipiente. Em relação à Revolução Francesa, a seus desdobramentos e às demais revoluções posteriores a ela até as primeiras décadas do século XX, julgue (C ou E) os ite', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História Mundial', NULL, 'Q51 Item 1 (TPS 2024): HISTÓRIA MUNDIAL CEBRASPE – IRBr – Edital: 2024 Por volta do final de abril, tudo se agravara. A fermentação transformara-se em fervura. Desde 1830, aqui e ali ocorriam pequenas rebeliões parciais, rapidamente sufocadas, mas recorrentes, sinal de vasta conflagração subjacente. Algo terrível incubava. Entreviam-se os lineamentos ainda mal distintos e poucos claros de uma possível revolução. Victor Hugo. Os miseráveis. São Paulo: Martin Claret, 2014, p. 884. Considerando o contexto histórico em qu | A participação feminina em premiações internacionais no alvorecer do século XX não conseguiu superar a representação das mulheres, segundo o ideário universal, como peças funcionais na família e na sociedade, a despeito de sua procura pelo reconhecimento público de seus feitos; prova disso é que, entre 1901 e 1914, quando a Fundação Prêmio Nobel começou a premiar personalidades no campo científico, apenas por quatro vezes, as mulheres, como Selma Lagerlöf, Bertha von St', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'História Mundial', NULL, 'Q51 Item 2 (TPS 2024): HISTÓRIA MUNDIAL CEBRASPE – IRBr – Edital: 2024 Por volta do final de abril, tudo se agravara. A fermentação transformara-se em fervura. Desde 1830, aqui e ali ocorriam pequenas rebeliões parciais, rapidamente sufocadas, mas recorrentes, sinal de vasta conflagração subjacente. Algo terrível incubava. Entreviam-se os lineamentos ainda mal distintos e poucos claros de uma possível revolução. Victor Hugo. Os miseráveis. São Paulo: Martin Claret, 2014, p. 884. Considerando o contexto histórico em qu | Durante os anos do apogeu do liberalismo clássico, ocorrido antes de 1914, o volume do comércio mundial dobrava a cada 20 ou 25 anos, ao passo que, após a Segunda Guerra Mundial, o volume do comércio mundial passou a dobrar a uma velocidade muito menor, em torno de três a quatro décadas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História Mundial', NULL, 'Q51 Item 3 (TPS 2024): HISTÓRIA MUNDIAL CEBRASPE – IRBr – Edital: 2024 Por volta do final de abril, tudo se agravara. A fermentação transformara-se em fervura. Desde 1830, aqui e ali ocorriam pequenas rebeliões parciais, rapidamente sufocadas, mas recorrentes, sinal de vasta conflagração subjacente. Algo terrível incubava. Entreviam-se os lineamentos ainda mal distintos e poucos claros de uma possível revolução. Victor Hugo. Os miseráveis. São Paulo: Martin Claret, 2014, p. 884. Considerando o contexto histórico em qu | As transformações técnicas e dos modos de vida que caracterizaram o período da Revolução Industrial entre 1875 e 1890 favoreceram o crescimento de correntes políticas apoiadas na democracia das massas, que, adiante, no século XX, estiveram integradas tanto ao nacionalismo, característico do liberalismo conservador, quanto ao socialismo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História Mundial', NULL, 'Q51 Item 4 (TPS 2024): HISTÓRIA MUNDIAL CEBRASPE – IRBr – Edital: 2024 Por volta do final de abril, tudo se agravara. A fermentação transformara-se em fervura. Desde 1830, aqui e ali ocorriam pequenas rebeliões parciais, rapidamente sufocadas, mas recorrentes, sinal de vasta conflagração subjacente. Algo terrível incubava. Entreviam-se os lineamentos ainda mal distintos e poucos claros de uma possível revolução. Victor Hugo. Os miseráveis. São Paulo: Martin Claret, 2014, p. 884. Considerando o contexto histórico em qu | Posteriormente à década de 70 do século XX, a riqueza no mundo atingiu altos patamares, o que possibilitou o aumento exponencial do financiamento de atividades culturais e artísticas, tendo sido, entretanto, toda essa riqueza global direcionada para o setor privado em detrimento das receitas públicas. Espaço livre', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História Mundial', NULL, 'Q52 Item 2 (TPS 2024): Ao estudioso das relações internacionais o principal foco está na interpretação do sentido e das implicações decorrentes dos fatos visíveis em dados ou em imagens transmitidas pelos noticiários. Pode-se pensar na questão como uma espécie de jogo de Lego: os acontecimentos, os fatos, os dados contidos em relatórios seriam como peças postas em uma caixa, mas a capacidade de reunir essas peças para formar figuras vai depender de recursos teóricos que permitam interpretar o significado e as conexões | No período entre as duas grandes guerras mundiais, os únicos países europeus com instituições políticas adequadamente democráticas que funcionaram sem interrupção foram a Grã-Bretanha, a Finlândia, o Estado Livre Irlandês, a Suécia e a Suíça.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História Mundial', NULL, 'Q52 Item 3 (TPS 2024): Ao estudioso das relações internacionais o principal foco está na interpretação do sentido e das implicações decorrentes dos fatos visíveis em dados ou em imagens transmitidas pelos noticiários. Pode-se pensar na questão como uma espécie de jogo de Lego: os acontecimentos, os fatos, os dados contidos em relatórios seriam como peças postas em uma caixa, mas a capacidade de reunir essas peças para formar figuras vai depender de recursos teóricos que permitam interpretar o significado e as conexões | Segundo o economista John Maynard Keynes, após a Primeira Guerra Mundial, sem a restauração da economia alemã, era impossível a recomposição de uma civilização e economia liberais estáveis na Europa, pensamento que influenciou os franceses a tolerar uma política de realização alemã após 1924, o que, mesmo assim e devido à longa relutância francesa, terminou por enfraquecer a economia na Alemanha.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'História Mundial', NULL, 'Q52 Item 4 (TPS 2024): Ao estudioso das relações internacionais o principal foco está na interpretação do sentido e das implicações decorrentes dos fatos visíveis em dados ou em imagens transmitidas pelos noticiários. Pode-se pensar na questão como uma espécie de jogo de Lego: os acontecimentos, os fatos, os dados contidos em relatórios seriam como peças postas em uma caixa, mas a capacidade de reunir essas peças para formar figuras vai depender de recursos teóricos que permitam interpretar o significado e as conexões | A Alemanha, após ter declarado guerra à URSS em 1941, não poderia manter uma guerra longa, pois, apesar de seus esforços, produzia bem menos aviões que seus rivais Inglaterra, URSS e Estados Unidos da América; depois da bem-sucedida ofensiva alemã contra as regiões do Cáucaso e do baixo Volga, as tropas germânicas foram detidas em Stalingrado, momento a partir do qual a derrota alemã foi apenas uma questão de tempo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História Mundial', NULL, 'Q53 Item 1 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Considerando os desdobramentos históricos relacionados à Guerra Fria, julgue (C ou E) os itens subsecutivos. | Um dos pontos centrais da convenção Bretton Woods, realizada em 1944 com o objetivo de evitar os erros das políticas econômicas dos anos 30 que culminaram na grande depressão, foi o compromisso firmado em prol da conversão das moedas europeias para o euro, com o objetivo de facilitar o comércio e os investimentos internacionais e alavancar a economia no continente europeu, destroçado pela guerra.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História Mundial', NULL, 'Q53 Item 2 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Considerando os desdobramentos históricos relacionados à Guerra Fria, julgue (C ou E) os itens subsecutivos. | Assim como ocorrera com a Holanda, que, após a Segunda Guerra Mundial, viu a Indonésia lutar e conseguir sua independência, as demais potências coloniais e ex-coloniais do oeste europeu passaram a dedicar sua total atenção às questões europeias e abandonaram as antigas prioridades de manter o domínio e o controle das respectivas colônias.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'História Mundial', NULL, 'Q53 Item 3 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Considerando os desdobramentos históricos relacionados à Guerra Fria, julgue (C ou E) os itens subsecutivos. | Na América do Sul, a aplicação da política econômica internacional conhecida como Consenso de Washington resultou em medidas que, algumas décadas depois, implicaram a adoção, pelos presidentes da Argentina e do Brasil, de políticas que modificassem os padrões das reformas liberais, indo contra as teses que embasaram o referido consenso.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História Mundial', NULL, 'Q53 Item 4 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Considerando os desdobramentos históricos relacionados à Guerra Fria, julgue (C ou E) os itens subsecutivos. | Paralelamente às consequências econômicas e políticas do colapso da URSS e da Europa Oriental, que foram mais dramáticas que as ocorridas na Europa Ocidental em fins da década de 80 do século passado, as ricas economias do capitalismo trataram a crise de forma urgente e maciça, tendo o fim da Guerra Fria sido considerado o fim de um conflito, e não o fim de uma era. No dia 18 de janeiro de 1871, por volta do meio-dia, ocorreu a proclamação do Império Alemão. O evento foi celebrado em uma luxuosa e solene cerimônia na Galeria dos Espelhos, um dos maiores salões do Palácio de Versalhes, na França. Naquela ocasião, o rei Guilherme I da Prússia tornou-se, aos 73 anos de idade, Kaiser Guilherme, com o desafio de unir todos os alemães em um único Estado. Em relação ao Império Alemão, mencionado ', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'História Mundial', NULL, 'Q55 Item 2 (TPS 2024): Em 29 de maio de 1913, estreou, na cidade de Paris, no Théâtre des Champs Élysées, o aguardado espetáculo de balé Le sacre du printemps (A sagração da primavera), que marcou para sempre a vida cultural do século XX, especialmente pela reação do público, que se dividiu, assim que os primeiros compassos foram ouvidos, entre aplausos entusiasmados de aprovação e gritos de protesto. A respeito do espetáculo mencionado no texto precedente e do contexto político e social da época em questão, julgue (C | A Sagração da primavera foi uma produção da companhia russa Ballets Russes, liderada pelo empresário russo Serguei Diaghilev e construída com a colaboração de grandes artistas, como Igor Stravinsky e Romola Nijinsky.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História Mundial', NULL, 'Q55 Item 4 (TPS 2024): Em 29 de maio de 1913, estreou, na cidade de Paris, no Théâtre des Champs Élysées, o aguardado espetáculo de balé Le sacre du printemps (A sagração da primavera), que marcou para sempre a vida cultural do século XX, especialmente pela reação do público, que se dividiu, assim que os primeiros compassos foram ouvidos, entre aplausos entusiasmados de aprovação e gritos de protesto. A respeito do espetáculo mencionado no texto precedente e do contexto político e social da época em questão, julgue (C | A reação negativa de parte do público à apresentação do referido espetáculo de balé pode ser atribuída a seu caráter disruptivo: os diálogos eram em russo, a música era conduzida por um coral formado de jovens com vozes estridentes, a bailarina principal usava roupas masculinas e ao palco foram levados animais (macacos emprestados pelo Cirque d’Hiver), o que foi interpretado como desrespeito e imoralismo pela burguesia parisiense. Acerca do colonialismo, do imperialismo', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'História Mundial', NULL, 'Q57 Item 1 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Julgue (C ou E) os próximos itens, concernentes a ideologias circulantes nos séculos XIX e XX bem como aos regimes políticos em tais séculos. | O keynesianismo emergiu com a crise liberal que se instalou no pós-1929, tomou corpo com o new deal de Franklin Roosevelt e com outras políticas do welfare state e ganhou mais força com o empenho de reconstrução da economia europeia no pós-1945, tendo, porém, se enfraquecido com as proposições de Milton Friedman e a supremacia neoliberal das duas últimas décadas do século passado.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'História Mundial', NULL, 'Q57 Item 2 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Julgue (C ou E) os próximos itens, concernentes a ideologias circulantes nos séculos XIX e XX bem como aos regimes políticos em tais séculos. | Na Confederação Germânica de meados do século XIX, em que se enfrentaram dois projetos políticos — o liberal-democrático e o militarista-conservador —, o processo de unificação nacional, comandado pelo prussiano Otto von Bismarck, se deu sob a orientação do primeiro projeto, herdeiro ideológico das revoluções de 1848.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'História Mundial', NULL, 'Q57 Item 3 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Julgue (C ou E) os próximos itens, concernentes a ideologias circulantes nos séculos XIX e XX bem como aos regimes políticos em tais séculos. | O regime de Vichy, que vigorou na França durante a Segunda Guerra Mundial, foi marcado por seu caráter antifascista e antiditatorial, evidente, sobretudo, na simpatia de Philippe Pétain pela causa dos que resistiam à ocupação alemã do território francês.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'História Mundial', NULL, 'Q57 Item 4 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Julgue (C ou E) os próximos itens, concernentes a ideologias circulantes nos séculos XIX e XX bem como aos regimes políticos em tais séculos. | A ideologia comunista, em sua versão marxista-leninista, e a fascista, em suas formas italiana e alemã, atualizaram um tema clássico da cultura política europeia: a crítica da abstração democrática moderna, em nome da antiga sociedade orgânica, pela direita, e da futura sociedade socialista, pela esquerda. ECONOMIA A presidência brasileira no BRICS será exercida em um contexto internacional marcado, entre outras discussões, pelo debate de parte dos países em desenvolvimento em torno do papel do dólar nas transações internacionais. Tendo como referência inicial as informações precedentes, julgue (C ou E) os itens a seguir, relativos às funções da moeda e ao papel da autoridade monetária. 1 A gestão da autoridade monetária sobre os investimentos das reservas internacionais não é afetada pelo', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Direito Internacional Público', NULL, 'Q59 Item 1 (TPS 2024): Considerando conceitos relacionados ao balanço de pagamentos bem como a sua estrutura, julgue (C ou E) os itens que se seguem. | A conta financeira do balanço de pagamentos, que registra todas as compras e vendas internacionais de ativos financeiros, direitos sobre recursos naturais, marcas, logotipos e domínios, contribui para a análise do movimento de capitais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Direito Internacional Público', NULL, 'Q59 Item 2 (TPS 2024): Considerando conceitos relacionados ao balanço de pagamentos bem como a sua estrutura, julgue (C ou E) os itens que se seguem. | As transferências unilaterais líquidas não são consideradas parte da conta-corrente, visto que, por sua natureza, elas não são resultado da compra e venda de nenhuma mercadoria, serviço ou ativo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Direito Internacional Público', NULL, 'Q59 Item 3 (TPS 2024): Considerando conceitos relacionados ao balanço de pagamentos bem como a sua estrutura, julgue (C ou E) os itens que se seguem. | Quando as importações de um país superam suas exportações, diz-se que o país tem déficit em conta-corrente; portanto, é correto concluir que, se um país compra mais dos estrangeiros do que vende a estes, ele precisará financiar a diferença por meio da aquisição de empréstimos externos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Direito Internacional Público', NULL, 'Q59 Item 4 (TPS 2024): Considerando conceitos relacionados ao balanço de pagamentos bem como a sua estrutura, julgue (C ou E) os itens que se seguem. | A equação Y = C + I + G + EX – IM mostra a identidade da renda nacional para uma economia aberta, e uma análise desses agregados indica a importância da conta-corrente no dimensionamento do empréstimo internacional. Frente à crise internacional nos anos de 2007 e 2008, o Comitê da Basileia (Basileia III), do qual o Brasil faz parte, buscou fomentar boas práticas nas instituições financeiras. Considerando o objetivo do Brasil de garantir a eficiência da intermediação de recursos e a promoção da estabilidade do Sistema Financeiro Nacional, julgue (C ou E) os itens subsequentes. 1 Em cumprimento às recomendações do Comitê da Basileia (Basileia III), o governo brasileiro tem buscado reduzir os requerimentos de liquidez e de alavancagem das instituições financeiras de grande porte para a melhor', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Direito Internacional Público', NULL, 'Q62 Item 1 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Em relação à macroeconomia internacional dos fluxos de bens e de capital, julgue (C ou E) os próximos itens. | Na contabilização do investimento estrangeiro direto, incluem-se apenas os capitais que tenham cruzado a fronteira para que se realizasse o investimento.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2024, 'Direito Internacional Público', NULL, 'Q62 Item 2 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Em relação à macroeconomia internacional dos fluxos de bens e de capital, julgue (C ou E) os próximos itens. | Um superávit comercial produz aumento no passivo da autoridade monetária, como um banco central, por exemplo, uma vez que as reservas cambiais são incluídas na base monetária do país.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Direito Internacional Público', NULL, 'Q62 Item 3 (TPS 2024): CEBRASPE – IRBr – Edital: 2024 Em relação à macroeconomia internacional dos fluxos de bens e de capital, julgue (C ou E) os próximos itens. | A maioria dos países em desenvolvimento tem quase nenhum fluxo de capitais, devido à falta de incentivos para investimento estrangeiro direto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL)
